<script setup lang="ts">import type{Company,Job}from'@career-launch/shared';import{onMounted,ref}from'vue';import{useRoute}from'vue-router';import{repository}from'../../services/repository';import JobCard from'../jobs/JobCard.vue';const route=useRoute();const company=ref<Company|null>(null);const jobs=ref<Job[]>([]);onMounted(async()=>{company.value=await repository.companies.get(String(route.params.id));jobs.value=(await repository.jobs.list({keyword:company.value.name,city:[],category:[],education:[],sort:'latest',page:1,pageSize:12})).items})</script>
<template><section v-if="company" class="cl-page cl-container"><header class="company-head"><span>{{company.logoText}}</span><div><h1>{{company.name}}</h1><p>{{company.industry}} · {{company.ownership}} · {{company.scale}}</p></div><a class="cl-quiet-button" :href="company.careersUrl" target="_blank" rel="noopener noreferrer">访问招聘官网</a></header><div class="about cl-card"><h2>公司介绍</h2><p>{{company.description}}</p><dl><div><dt>主要城市</dt><dd>{{company.cities.join('、')}}</dd></div><div><dt>公司规模</dt><dd>{{company.scale}}</dd></div><div><dt>公司性质</dt><dd>{{company.ownership}}</dd></div></dl></div><h2 class="jobs-title">正在招聘</h2><div class="job-grid"><JobCard v-for="job in jobs" :key="job.id" :job="job"/></div></section><section v-else class="cl-page cl-container">正在加载公司信息…</section></template>
<style scoped>.company-head{display:grid;grid-template-columns:70px 1fr auto;gap:18px;align-items:center;margin-bottom:24px}.company-head>span{width:70px;height:70px;display:grid;place-items:center;border-radius:16px;color:var(--cl-primary);background:var(--cl-primary-soft);font-size:26px;font-weight:800}.company-head h1{margin:0;color:var(--cl-text-strong);font-size:36px}.company-head p{margin:4px 0;color:var(--cl-muted)}.about{padding:26px}.about p{color:var(--cl-muted)}dl{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:24px 0 0}dl div{padding:14px;border-radius:8px;background:var(--cl-canvas)}dt{color:var(--cl-muted);font-size:12px}dd{margin:3px 0 0;font-weight:700}.jobs-title{margin:42px 0 18px}.job-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}@media(max-width:780px){.company-head{grid-template-columns:58px 1fr}.company-head>a{grid-column:1/-1}.job-grid{grid-template-columns:1fr}dl{grid-template-columns:1fr}}</style>
